{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:umf:core:0.3.0",
  "title": "UMF 0.3.0 nullability envelope",
  "type": "object",
  "required": [
    "umf",
    "id",
    "vocabularies",
    "modules"
  ],
  "properties": {
    "umf": {
      "const": "0.3.0"
    },
    "id": {
      "$ref": "#/$defs/id"
    },
    "vocabularies": {
      "type": "object",
      "propertyNames": {
        "$ref": "#/$defs/id"
      },
      "additionalProperties": {
        "type": "object",
        "required": [
          "version"
        ],
        "properties": {
          "version": {
            "$ref": "#/$defs/version"
          }
        }
      }
    },
    "modules": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/module"
      }
    },
    "extensions": {
      "$ref": "#/$defs/extensions"
    }
  },
  "$defs": {
    "id": {
      "type": "string",
      "minLength": 1
    },
    "version": {
      "type": "string",
      "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)$"
    },
    "knownScalarType": {
      "enum": [
        "boolean",
        "integer",
        "decimal",
        "float",
        "string",
        "binary",
        "date",
        "time",
        "timestamp"
      ],
      "description": "Basic value families; native refinements remain authoritative for ranges, precision, encoding and temporal behavior."
    },
    "scalarType": {
      "anyOf": [
        {
          "$ref": "#/$defs/knownScalarType"
        },
        {
          "type": "string",
          "minLength": 1,
          "not": {
            "$ref": "#/$defs/knownScalarType"
          },
          "description": "Unknown family retained with incomplete semantic validation."
        }
      ]
    },
    "extensions": {
      "type": "object",
      "propertyNames": {
        "$ref": "#/$defs/id"
      },
      "additionalProperties": true
    },
    "reference": {
      "type": "object",
      "required": [
        "role",
        "module",
        "element"
      ],
      "properties": {
        "role": {
          "$ref": "#/$defs/id"
        },
        "module": {
          "$ref": "#/$defs/id"
        },
        "element": {
          "$ref": "#/$defs/id"
        }
      }
    },
    "element": {
      "type": "object",
      "required": [
        "id",
        "extensions"
      ],
      "properties": {
        "id": {
          "$ref": "#/$defs/id"
        },
        "name": {
          "type": "string"
        },
        "description": {
          "type": "string"
        },
        "scalarType": {
          "$ref": "#/$defs/scalarType"
        },
        "extensions": {
          "$ref": "#/$defs/extensions"
        },
        "references": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/reference"
          }
        },
        "kind": {
          "type": "string",
          "minLength": 1,
          "description": "UMF role; unknown labels remain uninterpreted. Missing is unspecified, never inferred from scalarType."
        },
        "nullability": {
          "type": "string",
          "minLength": 1,
          "description": "Ideal value availability. Unknown labels remain uninterpreted. Missing and unspecified assert no availability constraint. Native absence carriers require explicit bindings."
        }
      },
      "allOf": [
        {
          "if": {
            "required": [
              "kind"
            ],
            "properties": {
              "kind": {
                "enum": [
                  "record",
                  "group"
                ]
              }
            }
          },
          "then": {
            "properties": {
              "scalarType": false
            }
          }
        },
        {
          "if": {
            "required": [
              "nullability"
            ],
            "properties": {
              "nullability": {}
            }
          },
          "then": {
            "required": [
              "kind"
            ],
            "properties": {
              "kind": {
                "const": "field"
              }
            }
          }
        }
      ]
    },
    "module": {
      "type": "object",
      "required": [
        "id",
        "namespace",
        "elements"
      ],
      "properties": {
        "id": {
          "$ref": "#/$defs/id"
        },
        "namespace": {
          "type": "string"
        },
        "elements": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/element"
          }
        },
        "extensions": {
          "$ref": "#/$defs/extensions"
        }
      }
    },
    "knownElementKind": {
      "enum": [
        "field",
        "record",
        "group"
      ]
    },
    "knownNullability": {
      "enum": [
        "required",
        "absent-allowed",
        "unspecified"
      ]
    }
  },
  "description": "Explicit ideal value availability on Fields. No implicit upgrade from older envelopes, native NULL mapping, or default execution."
}
